-- Expanded seed script with realistic high-resolution destination imagery and rich activities.
INSERT INTO cities (name, country, country_code, region, description, image, cost_index, popularity, latitude, longitude)
VALUES
  ('Jaipur', 'India', 'IN', 'Rajasthan', 'The legendary Pink City of Rajasthan famed for magnificent forts, royal palaces, bustling bazaars, and vibrant Rajasthani heritage.', 'https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=1200&q=80', 32.00, 97, 26.912434, 75.787270),
  ('Mumbai', 'India', 'IN', 'Maharashtra', 'India''s financial capital and entertainment hub featuring the Gateway of India, Marine Drive, Bollywood, and world-class street food.', 'https://images.unsplash.com/photo-1568454537842-d933259bb258?auto=format&fit=crop&w=1200&q=80', 45.00, 98, 19.076090, 72.877426),
  ('Goa', 'India', 'IN', 'Goa', 'India''s premier beach paradise famous for golden sands, Portuguese heritage forts, spice plantations, and vibrant coastal culture.', 'https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=1200&q=80', 38.00, 99, 15.299300, 74.124000),
  ('Paris', 'France', 'FR', 'Île-de-France', 'France''s iconic capital, famous for the Eiffel Tower, world-class museums, and romantic boulevard cafés.', 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=1200&q=80', 82.50, 98, 48.856613, 2.352222),
  ('Rome', 'Italy', 'IT', 'Lazio', 'Historic capital with ancient ruins, Renaissance art, authentic gelato, and vibrant piazzas.', 'https://images.unsplash.com/photo-1552832230-c0197dd311b5?auto=format&fit=crop&w=1200&q=80', 71.25, 95, 41.902782, 12.496366),
  ('Tokyo', 'Japan', 'JP', 'Kantō', 'A soaring metropolis seamlessly blending futuristic skyscrapers, neon alleys, and ancient temples.', 'https://images.unsplash.com/photo-1540959733332-eab4deabeeaf?auto=format&fit=crop&w=1200&q=80', 88.00, 99, 35.676200, 139.650000),
  ('Lisbon', 'Portugal', 'PT', 'Lisbon District', 'A sunlit coastal city known for pastel-hued buildings, scenic miradouros, and historic yellow trams.', 'https://images.unsplash.com/photo-1555881400-74d7acaacd8b?auto=format&fit=crop&w=1200&q=80', 57.75, 87, 38.722252, -9.139337),
  ('New York City', 'United States', 'US', 'New York', 'The global epicenter of culture, finance, and entertainment featuring Broadway and Central Park.', 'https://images.unsplash.com/photo-1496442226666-8d4d0e62e6e9?auto=format&fit=crop&w=1200&q=80', 95.00, 98, 40.712776, -74.005974),
  ('London', 'United Kingdom', 'GB', 'Greater London', 'A majestic capital steeped in royal history, world-renowned theaters, and diverse dining.', 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=1200&q=80', 89.00, 97, 51.507351, -0.127758),
  ('Barcelona', 'Spain', 'ES', 'Catalonia', 'A Mediterranean jewel celebrated for Gaudí architecture, golden beaches, and lively tapas bars.', 'https://images.unsplash.com/photo-1583422409516-2895a77efded?auto=format&fit=crop&w=1200&q=80', 68.00, 94, 41.385064, 2.173403),
  ('Kyoto', 'Japan', 'JP', 'Kansai', 'The cultural heart of Japan filled with thousands of classical Buddhist temples, gardens, and geisha districts.', 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=1200&q=80', 76.00, 93, 35.011636, 135.768029),
  ('Amsterdam', 'Netherlands', 'NL', 'North Holland', 'Famous for its picturesque canal ring, historic gabled townhouses, and world-class bike lanes.', 'https://images.unsplash.com/photo-1512470876302-972faa2aa9a4?auto=format&fit=crop&w=1200&q=80', 84.00, 91, 52.367573, 4.904138),
  ('Sydney', 'Australia', 'AU', 'New South Wales', 'A breathtaking harbor city with landmark architecture, coastal walks, and world-famous surfing beaches.', 'https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=1200&q=80', 86.00, 92, -33.868820, 151.209296),
  ('Dubai', 'United Arab Emirates', 'AE', 'Dubai', 'An ultra-modern oasis of luxury shopping, futuristic architecture, and desert adventures.', 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=1200&q=80', 92.00, 95, 25.204849, 55.270783),
  ('Rio de Janeiro', 'Brazil', 'BR', 'Rio de Janeiro', 'A vibrant tropical metropolis framed by Sugarloaf Mountain, Copacabana, and samba music.', 'https://images.unsplash.com/photo-1483729558449-99ef09a8c325?auto=format&fit=crop&w=1200&q=80', 54.00, 89, -22.906847, -43.172896),
  ('Cape Town', 'South Africa', 'ZA', 'Western Cape', 'A stunning coastal city anchored by dramatic Table Mountain, wineries, and Atlantic shores.', 'https://images.unsplash.com/photo-1580619305218-8423a7ef79b4?auto=format&fit=crop&w=1200&q=80', 52.00, 88, -33.924869, 18.424055),
  ('Bangkok', 'Thailand', 'TH', 'Bangkok', 'An energetic capital filled with ornate shrines, bustling street food markets, and riverways.', 'https://images.unsplash.com/photo-1508009603885-50cf7c579365?auto=format&fit=crop&w=1200&q=80', 45.00, 96, 13.756331, 100.501765),
  ('Venice', 'Italy', 'IT', 'Veneto', 'An enchanted floating city of romantic canals, gothic palaces, and marble bridges.', 'https://images.unsplash.com/photo-1514890547357-a9ee288728e0?auto=format&fit=crop&w=1200&q=80', 85.00, 93, 45.440847, 12.315515),
  ('Istanbul', 'Turkey', 'TR', 'Marmara', 'A historic crossroad connecting Europe and Asia across the scenic Bosphorus strait.', 'https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=1200&q=80', 48.00, 92, 41.008238, 28.978359),
  ('Singapore', 'Singapore', 'SG', 'Central', 'A lush garden city known for futuristic Supertrees, Marina Bay skyline, and hawker cuisine.', 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=1200&q=80', 91.00, 94, 1.352083, 103.819836),
  ('Prague', 'Czech Republic', 'CZ', 'Prague', 'A fairytale city of spires, baroque churches, and the iconic 14th-century Charles Bridge.', 'https://images.unsplash.com/photo-1541849546-216549ae216d?auto=format&fit=crop&w=1200&q=80', 60.00, 90, 50.075538, 14.437800),
  ('Cairo', 'Egypt', 'EG', 'Cairo Governorate', 'The ancient city on the Nile, gateway to the Great Pyramids and Egyptian museum treasures.', 'https://images.unsplash.com/photo-1503177119275-0aa32b3a9368?auto=format&fit=crop&w=1200&q=80', 42.00, 91, 30.044420, 31.235712)
ON CONFLICT (name, country, region) DO UPDATE SET
  image = EXCLUDED.image,
  description = EXCLUDED.description,
  cost_index = EXCLUDED.cost_index,
  popularity = EXCLUDED.popularity;

-- Activities seeding
INSERT INTO activities (city_id, name, description, category, duration_minutes, estimated_cost, image)
SELECT c.id, v.name, v.description, v.category, v.duration_minutes, v.estimated_cost, v.image
FROM (
  VALUES
    ('Jaipur', 'Amber Fort & Palace Light Show', 'Explore the stunning 16th-century hilltop Amber Fort with elephant rides and the spectacular evening Amer Sound & Light Show.', 'culture', 180, 1200.00, 'https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=800&q=80'),
    ('Jaipur', 'City Palace & Maharaja Museum Tour', 'Visit the magnificent royal residence of the Maharaja of Jaipur with its ornate courtyards, textiles, and artifacts.', 'culture', 120, 700.00, 'https://images.unsplash.com/photo-1627894006066-b4f4d2c0d3d2?auto=format&fit=crop&w=800&q=80'),
    ('Jaipur', 'Hawa Mahal & Old City Pink Walk', 'Walk through the iconic Palace of Winds and explore the vibrant bazaars of the walled Pink City.', 'sightseeing', 150, 400.00, 'https://images.unsplash.com/photo-1580587771525-78b9dba3b914?auto=format&fit=crop&w=800&q=80'),
    ('Jaipur', 'Nahargarh Fort Sunset & Royal Dinner', 'Trek or drive to the hilltop Nahargarh Fort at sunset for panoramic city views followed by a rooftop Rajasthani thali dinner.', 'food', 210, 1800.00, 'https://images.unsplash.com/photo-1535530992830-e25d07cfa780?auto=format&fit=crop&w=800&q=80'),
    ('Jaipur', 'Jaipur Gem & Jewellery Factory Tour', 'Behind-the-scenes tour of Rajasthan''s world-famous gem-cutting workshops and showrooms in the Johari Bazaar district.', 'shopping', 90, 250.00, 'https://images.unsplash.com/photo-1512291313931-d4291048e7b6?auto=format&fit=crop&w=800&q=80'),
    ('Jaipur', 'Jantar Mantar Astronomical Observatory', 'Explore the UNESCO-listed 18th-century astronomical observatory with its massive stone instruments for tracking celestial bodies.', 'culture', 60, 300.00, 'https://images.unsplash.com/photo-1599661046289-e31897846e41?auto=format&fit=crop&w=800&q=80'),
    ('Jaipur', 'Desert Camel Safari & Cultural Village', 'Enjoy an evening camel safari through sand dunes on the outskirts of Jaipur with folk music and village cuisine experience.', 'outdoor', 240, 1500.00, 'https://images.unsplash.com/photo-1469854523086-cc02fe5d8800?auto=format&fit=crop&w=800&q=80'),
    ('Mumbai', 'Gateway of India & Elephanta Caves Boat Trip', 'Ferry ride from the iconic Gateway of India to Elephanta Island to explore ancient rock-cut Shiva temples and sculptures.', 'culture', 240, 800.00, 'https://images.unsplash.com/photo-1568454537842-d933259bb258?auto=format&fit=crop&w=800&q=80'),
    ('Mumbai', 'Dharavi Slum Reality & Street Food Walk', 'Eye-opening guided tour of Asia''s largest slum showcasing entrepreneurship, leather workshops, recycling hubs, and local snacks.', 'culture', 150, 1200.00, 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?auto=format&fit=crop&w=800&q=80'),
    ('Mumbai', 'Marine Drive Sunset & Chowpatty Street Food', 'Evening stroll along the Queen''s Necklace waterfront and authentic Mumbai street food — vada pav, pav bhaji, and bhel puri.', 'food', 90, 400.00, 'https://images.unsplash.com/photo-1567157577867-05ccb1388e66?auto=format&fit=crop&w=800&q=80'),
    ('Mumbai', 'Bollywood Film City Studio Tour', 'Guided tour of the massive Bollywood studio complex with live sets, costume rooms, and a chance to see filmings in action.', 'entertainment', 180, 1500.00, 'https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?auto=format&fit=crop&w=800&q=80'),
    ('Goa', 'Calangute & Baga Water Sports Combo', 'Experience parasailing, jet skiing, banana rides, and speedboats along Goa''s famous northern beaches.', 'outdoor', 180, 2500.00, 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80'),
    ('Goa', 'Dudhsagar Waterfall Jeep Safari & Trek', 'Thrilling off-road 4x4 safari through Bhagwan Mahavir Wildlife Sanctuary to the majestic four-tiered waterfalls.', 'outdoor', 360, 2200.00, 'https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=800&q=80'),
    ('Goa', 'Fort Aguada & Lighthouse Guided Tour', 'Explore the 17th-century Portuguese fortress overlooking the Arabian Sea and historic lighthouse.', 'culture', 120, 300.00, 'https://images.unsplash.com/photo-1512343879784-a960bf40e7f2?auto=format&fit=crop&w=800&q=80'),
    ('Goa', 'Sahakari Spice Plantation Tour & Buffet Lunch', 'Walk through lush cardamom, vanilla, and pepper plantations with traditional Goan buffet and herbal tea.', 'food', 180, 800.00, 'https://images.unsplash.com/photo-1596040033229-a9821ebd058d?auto=format&fit=crop&w=800&q=80'),
    ('Goa', 'Mandovi River Sunset Cruise & Folk Dance', 'Enjoy a 1-hour sunset boat cruise along Mandovi River featuring live Goan cultural performances and music.', 'sightseeing', 90, 600.00, 'https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=800&q=80'),
    ('Goa', 'Old Goa Basilica of Bom Jesus & Cathedral Walk', 'Guided visit to UNESCO World Heritage Portuguese churches housing the tomb of St. Francis Xavier.', 'culture', 150, 250.00, 'https://images.unsplash.com/photo-1548013146-72479768bada?auto=format&fit=crop&w=800&q=80'),
    ('Goa', 'Grand Island Scuba Diving & Dolphin Trip', 'Speedboat trip to Grand Island for introductory scuba diving, snorkeling, and dolphin watching with lunch.', 'outdoor', 300, 2800.00, 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80'),
    ('Paris', 'Louvre Museum Guided Tour', 'Explore landmark artworks including the Mona Lisa and Venus de Milo.', 'culture', 180, 2250.00, 'https://images.unsplash.com/photo-1564399579883-451a5d44ec08?auto=format&fit=crop&w=800&q=80'),
    ('Paris', 'Seine River Sunset Cruise', 'See illuminated Paris landmarks from the water with live audio guide.', 'sightseeing', 75, 1800.00, 'https://images.unsplash.com/photo-1502602898657-3e91760cbb34?auto=format&fit=crop&w=800&q=80'),
    ('Rome', 'Colosseum & Forum Skip-the-Line', 'Guided walkthrough of Rome''s iconic ancient amphitheater and forum ruins.', 'culture', 210, 3200.00, 'https://images.unsplash.com/photo-1552832230-c0197dd311b5?auto=format&fit=crop&w=800&q=80'),
    ('Rome', 'Trastevere Food & Wine Walk', 'Sample authentic Roman pasta, pizza, and regional wine in historic Trastevere.', 'food', 150, 4500.00, 'https://images.unsplash.com/photo-1529260830199-42c24126f198?auto=format&fit=crop&w=800&q=80'),
    ('Tokyo', 'Senso-ji Temple Morning Visit', 'Morning walk through Asakusa''s traditional shopping street to Tokyo''s oldest temple.', 'culture', 90, 500.00, 'https://images.unsplash.com/photo-1542931287-023b922fa89b?auto=format&fit=crop&w=800&q=80'),
    ('Tokyo', 'Shibuya Crossing Photo Tour', 'Experience Shibuya''s world-famous scramble crossing and hidden izakaya alleys.', 'sightseeing', 120, 1200.00, 'https://images.unsplash.com/photo-1542051841857-5f90071e7989?auto=format&fit=crop&w=800&q=80'),
    ('Lisbon', 'Alfama Historic District Walk', 'Discover Lisbon''s oldest neighborhood, winding cobblestone streets, and ocean viewpoints.', 'sightseeing', 150, 1500.00, 'https://images.unsplash.com/photo-1555881400-74d7acaacd8b?auto=format&fit=crop&w=800&q=80'),
    ('Lisbon', 'Fado Performance & Portuguese Dinner', 'Enjoy soulful live Fado music alongside traditional bacalhau dinner.', 'entertainment', 180, 5200.00, 'https://images.unsplash.com/photo-1513735492246-483525079686?auto=format&fit=crop&w=800&q=80'),
    ('New York City', 'Central Park Bicycle Tour', 'Guided bike ride through Central Park visiting Bethesda Terrace and Strawberry Fields.', 'outdoor', 120, 3800.00, 'https://images.unsplash.com/photo-1519501025264-65ba15a82390?auto=format&fit=crop&w=800&q=80'),
    ('New York City', 'Broadway Show Experience', 'Attend a award-winning musical performance in Manhattan''s famous Theater District.', 'entertainment', 180, 9800.00, 'https://images.unsplash.com/photo-1507676184212-d03ab07a01bf?auto=format&fit=crop&w=800&q=80'),
    ('London', 'Tower of London & Crown Jewels', 'Explore the 900-year-old fortress and view the British Crown Jewels.', 'culture', 150, 3200.00, 'https://images.unsplash.com/photo-1513635269975-59663e0ac1ad?auto=format&fit=crop&w=800&q=80'),
    ('London', 'Thames Afternoon Tea Cruise', 'Traditional English afternoon tea served while cruising past Big Ben and London Eye.', 'food', 90, 4800.00, 'https://images.unsplash.com/photo-1533929736458-ca588d08c8be?auto=format&fit=crop&w=800&q=80'),
    ('Barcelona', 'Sagrada Familia Fast Track Tour', 'Marvel at Gaudí''s masterpiece basilica with an expert architecture guide.', 'culture', 120, 2800.00, 'https://images.unsplash.com/photo-1583422409516-2895a77efded?auto=format&fit=crop&w=800&q=80'),
    ('Barcelona', 'Gothic Quarter Tapas Crawl', 'Taste authentic Spanish jamón, patatas bravas, and sangria in medieval plazas.', 'food', 150, 3800.00, 'https://images.unsplash.com/photo-1539185441755-769473a23570?auto=format&fit=crop&w=800&q=80'),
    ('Kyoto', 'Fushimi Inari Torii Gate Hike', 'Walk beneath thousands of vermilion torii gates winding up Mount Inari.', 'outdoor', 150, 300.00, 'https://images.unsplash.com/photo-1493976040374-85c8e12f0c0e?auto=format&fit=crop&w=800&q=80'),
    ('Kyoto', 'Arashiyama Bamboo Grove Walk', 'Stroll through the towering green bamboo stalks and nearby Zen temple gardens.', 'outdoor', 120, 800.00, 'https://images.unsplash.com/photo-1503899036084-c55cdd92da26?auto=format&fit=crop&w=800&q=80'),
    ('Amsterdam', 'Canal Ring Cruise', 'Glide along Amsterdam''s UNESCO-listed 17th-century canal district.', 'sightseeing', 75, 1800.00, 'https://images.unsplash.com/photo-1512470876302-972faa2aa9a4?auto=format&fit=crop&w=800&q=80'),
    ('Amsterdam', 'Rijksmuseum Art Tour', 'View Dutch Golden Age masterpieces including Rembrandt''s Night Watch.', 'culture', 150, 2400.00, 'https://images.unsplash.com/photo-1584003564911-a7a321c84e1c?auto=format&fit=crop&w=800&q=80'),
    ('Sydney', 'Sydney Opera House Architecture Tour', 'Step inside the iconic sails and learn the story behind the architectural wonder.', 'culture', 60, 2500.00, 'https://images.unsplash.com/photo-1506973035872-a4ec16b8e8d9?auto=format&fit=crop&w=800&q=80'),
    ('Sydney', 'Bondi to Coogee Coastal Walk', 'Scenic cliffside coastal trek connecting Sydney''s famous golden beaches.', 'outdoor', 180, 400.00, 'https://images.unsplash.com/photo-1523428096881-5bd79d04300f?auto=format&fit=crop&w=800&q=80'),
    ('Dubai', 'Burj Khalifa At The Top Ticket', 'Ascend to the 124th floor observation deck for 360-degree desert skyline views.', 'sightseeing', 90, 4200.00, 'https://images.unsplash.com/photo-1512453979798-5ea266f8880c?auto=format&fit=crop&w=800&q=80'),
    ('Dubai', 'Desert Safari & BBQ Dinner', 'Dune bashing, camel riding, and traditional Bedouin dinner under the stars.', 'outdoor', 360, 6500.00, 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=800&q=80'),
    ('Rio de Janeiro', 'Christ the Redeemer & Corcovado Train', 'Ride the cog train through Tijuca Forest to the iconic Christ the Redeemer statue.', 'sightseeing', 180, 2800.00, 'https://images.unsplash.com/photo-1483729558449-99ef09a8c325?auto=format&fit=crop&w=800&q=80'),
    ('Cape Town', 'Table Mountain Aerial Cableway', 'Ascend Table Mountain via revolving cable car for panoramic ocean and city views.', 'outdoor', 120, 2200.00, 'https://images.unsplash.com/photo-1580619305218-8423a7ef79b4?auto=format&fit=crop&w=800&q=80'),
    ('Bangkok', 'Grand Palace & Wat Phra Kaew', 'Explore Thailand''s royal complex and the sacred Temple of the Emerald Buddha.', 'culture', 150, 1400.00, 'https://images.unsplash.com/photo-1508009603885-50cf7c579365?auto=format&fit=crop&w=800&q=80'),
    ('Venice', 'Gondola Ride along Grand Canal', 'Classic Venetian gondola experience through romantic backwater canals.', 'sightseeing', 45, 7500.00, 'https://images.unsplash.com/photo-1514890547357-a9ee288728e0?auto=format&fit=crop&w=800&q=80'),
    ('Istanbul', 'Hagia Sophia & Blue Mosque Guided Tour', 'Step into centuries of Byzantine and Ottoman history in Old Istanbul.', 'culture', 150, 1800.00, 'https://images.unsplash.com/photo-1524231757912-21f4fe3a7200?auto=format&fit=crop&w=800&q=80'),
    ('Singapore', 'Gardens by the Bay & Supertree Observatory', 'Discover futuristic bio-domes and the luminous Supertree Grove sound show.', 'outdoor', 150, 2100.00, 'https://images.unsplash.com/photo-1525625293386-3f8f99389edd?auto=format&fit=crop&w=800&q=80'),
    ('Prague', 'Charles Bridge Sunset Walk', 'Cross Prague''s historic stone bridge lined with saint statues as evening sets in.', 'sightseeing', 60, 500.00, 'https://images.unsplash.com/photo-1541849546-216549ae216d?auto=format&fit=crop&w=800&q=80'),
    ('Cairo', 'Giza Pyramids & Great Sphinx Day Tour', 'Marvel at the ancient Pyramids of Khufu, Khafre, and Menkaure with Egyptologist guide.', 'culture', 240, 3400.00, 'https://images.unsplash.com/photo-1503177119275-0aa32b3a9368?auto=format&fit=crop&w=800&q=80')
) AS v(city_name, name, description, category, duration_minutes, estimated_cost, image)
JOIN cities c ON c.name = v.city_name
ON CONFLICT (city_id, name) DO UPDATE SET
  description = EXCLUDED.description,
  category = EXCLUDED.category,
  duration_minutes = EXCLUDED.duration_minutes,
  estimated_cost = EXCLUDED.estimated_cost,
  image = EXCLUDED.image;
